/// <summary>
/// ATL specification of one expected MD31 archive row (SJPMDItemMasterArchive).
/// Only the fields set with with... are compared.
/// </summary>
public final class TEST_AtlSpecMD31ArchiveRow extends AtlSpecification
{
}

Method.Source:
public static TEST_AtlSpecMD31ArchiveRow construct()
{
    return new TEST_AtlSpecMD31ArchiveRow();
}

public TEST_AtlSpecMD31ArchiveRow withSkuCode(SJPMDItemMasterJANCode _skuCode)
{
    this.parmExpectedFieldValue(fieldNum(SJPMDItemMasterArchive, sku_cd), _skuCode);

    return this;
}

public TEST_AtlSpecMD31ArchiveRow withStatus(SJPMDInventImportStatus _status)
{
    this.parmExpectedFieldValue(fieldNum(SJPMDItemMasterArchive, Status), _status);

    return this;
}
